  ('lesser-white-toothed-shrew', 'Lesser White-toothed Shrew', 'Crocidura suaveolens', 'land-mammals', 'A tiny, pale-bellied shrew with a bristly tail, found in Britain only on the Isles of Scilly.', 'Hedges, walls, fields and shores on the Isles of Scilly', 'Year-round; seek local guidance on the islands'),
  ('common-pipistrelle', 'Common Pipistrelle', 'Pipistrellus pipistrellus', 'bats', 'A tiny, fast bat and one of the UK''s most widespread, often seen around gardens at dusk.', 'Gardens, woodland edges, hedgerows and water', 'From dusk, April to October; a bat detector helps'),
  ('noctule', 'Noctule', 'Nyctalus noctula', 'bats', 'One of the UK''s largest bats, with a high, fast flight, often emerging early at dusk.', 'Open woodland, parkland and water', 'May to September, shortly after sunset'),
  ('daubentons-bat', 'Daubenton''s Bat', 'Myotis daubentonii', 'bats', 'A bat that skims low over calm water to catch insects.', 'Rivers, canals and still water with nearby trees', 'Summer evenings after dusk, over calm water'),
  ('greater-horseshoe-bat', 'Greater Horseshoe Bat', 'Rhinolophus ferrumequinum', 'bats', 'A large bat with a horseshoe-shaped nose-leaf, found in south-west England and south Wales.', 'Caves, old buildings and pasture with grazing cattle', 'Summer evenings; join an organised roost event, as roosts are protected'),
  ('grey-seal', 'Grey Seal', 'Halichoerus grypus', 'marine-mammals', 'A large seal with a long, sloping nose; Britain hosts a globally important share of the world population.', 'Rocky coasts, sandbanks and offshore islands', 'Autumn pupping season at colonies; keep your distance'),
  ('harbour-seal', 'Harbour Seal', 'Phoca vitulina', 'marine-mammals', 'A smaller seal with a rounded, dog-like face, also called the common seal.', 'Estuaries, sandbanks and sheltered coasts', 'Low-tide haul-outs; summer pupping season'),
  ('harbour-porpoise', 'Harbour Porpoise', 'Phocoena phocoena', 'marine-mammals', 'The UK''s smallest cetacean, a shy, dark animal with a small triangular fin.', 'Coastal waters, tidal races and headlands', 'Calm summer days, watching from headlands'),
  ('bottlenose-dolphin', 'Bottlenose Dolphin', 'Tursiops truncatus', 'marine-mammals', 'A large, sociable dolphin with a short beak, resident in places like the Moray Firth and Cardigan Bay.', 'Coastal waters and estuaries', 'Summer, from boat trips or headlands'),
  ('minke-whale', 'Minke Whale', 'Balaenoptera acutorostrata', 'marine-mammals', 'The UK''s smallest baleen whale, usually seen as a curved back and small fin.', 'Open coastal and offshore waters', 'Summer boat trips, especially off the Hebrides'),
  ('adder', 'Adder', 'Vipera berus', 'reptiles', 'Britain''s only venomous native snake, with a dark zigzag along its back; never handle one.', 'Heathland, moorland, rough grassland and woodland edges', 'March to October; sunny mornings after hibernation'),
  ('grass-snake', 'Grass Snake', 'Natrix helvetica', 'reptiles', 'A large, harmless snake with a yellow and black collar, often found near water.', 'Wetlands, ponds, rough grassland and gardens with compost heaps', 'April to September on warm, sunny days'),
  ('common-lizard', 'Common Lizard', 'Zootoca vivipara', 'reptiles', 'A small, fast, brown lizard that gives birth to live young.', 'Heathland, grassland, moorland and woodland edges', 'Sunny spring and autumn days when basking'),
  ('slow-worm', 'Slow Worm', 'Anguis fragilis', 'reptiles', 'A legless lizard that looks like a snake but has eyelids and can drop its tail.', 'Gardens, grassland, heathland and compost heaps', 'Mild, overcast days; check under warm refuges'),
  ('smooth-snake', 'Smooth Snake', 'Coronella austriaca', 'reptiles', 'A slender, secretive snake restricted to a few southern heathlands and strictly protected.', 'Dry lowland heathland in southern England', 'April to September; very hard to find, so join a guided walk'),
  ('sand-lizard', 'Sand Lizard', 'Lacerta agilis', 'reptiles', 'A stocky, patterned lizard whose males turn bright green in spring; restricted to a few protected heathland and dune sites.', 'Sandy heathland and coastal sand dunes', 'April to September on warm, sunny days; protected, so never handle or disturb'),
  ('common-wall-lizard', 'Common Wall Lizard', 'Podarcis muralis', 'reptiles', 'A slim, agile, brown-grey lizard that basks on sunny walls and rocks; a southern European species breeding in a few long-established colonies.', 'Sunny walls, rocky banks, quarries and cliffs', 'Sunny days from spring to autumn, on south-facing walls; seek local guidance'),
  ('aesculapian-snake', 'Aesculapian Snake', 'Zamenis longissimus', 'reptiles', 'A long, slender, olive-brown snake that climbs well; native to continental Europe, with a few breeding colonies in Britain.', 'Warm, sheltered, wooded spots near water, and old buildings', 'Warm summer days; seek local guidance'),
  ('common-frog', 'Common Frog', 'Rana temporaria', 'amphibians', 'A familiar brown or olive frog that spawns in clumps in garden and woodland ponds.', 'Ponds, gardens, damp grassland and woodland', 'Spawning from late winter; tadpoles in spring'),
  ('common-toad', 'Common Toad', 'Bufo bufo', 'amphibians', 'A warty, brown toad that walks rather than hops and migrates to ponds in spring.', 'Woodland, gardens, grassland and ponds', 'Spring migration on mild, damp evenings'),
  ('smooth-newt', 'Smooth Newt', 'Lissotriton vulgaris', 'amphibians', 'A small newt; breeding males have a spotted belly and a wavy crest.', 'Garden ponds, ditches and ponds', 'March to June, in breeding ponds'),
  ('palmate-newt', 'Palmate Newt', 'Lissotriton helveticus', 'amphibians', 'A very small newt with a pale throat and webbed back feet, favouring acidic water.', 'Heathland pools, moorland ponds and woodland pools', 'March to June, in breeding ponds'),
  ('great-crested-newt', 'Great Crested Newt', 'Triturus cristatus', 'amphibians', 'Britain''s largest newt, with a jagged crest on breeding males; strictly protected by law.', 'Well-vegetated ponds and surrounding rough grassland', 'Spring; observe without handling and never disturb ponds'),
  ('natterjack-toad', 'Natterjack Toad', 'Epidalea calamita', 'amphibians', 'A yellow-striped toad that runs rather than hops and has a loud, rolling call.', 'Coastal dunes, sandy heaths and saltmarsh', 'April to June, at evening choruses'),
  ('pool-frog', 'Pool Frog', 'Pelophylax lessonae', 'amphibians', 'A small green-brown frog with a pale stripe down its back and a loud, rattling call; one of Britain''s rarest amphibians, reintroduced to Norfolk.', 'Clean, weedy ponds in Norfolk', 'May to July; listen at dusk for the call; seek local guidance'),
  ('brown-trout', 'Brown Trout', 'Salmo trutta', 'freshwater-fish', 'A native fish with spotted flanks; the sea trout is the same species in its migratory form.', 'Clear, cool rivers and lakes', 'Spring to autumn'),
  ('atlantic-salmon', 'Atlantic Salmon', 'Salmo salar', 'freshwater-fish', 'A migratory fish famed for leaping weirs on its way upstream to spawn.', 'Rivers and the sea', 'Autumn runs; some rivers earlier in the year'),
  ('northern-pike', 'Northern Pike', 'Esox lucius', 'freshwater-fish', 'A long ambush predator with a duck-bill snout and sharp teeth.', 'Slow rivers, lakes, canals and reed-fringed margins', 'Spring to autumn, in clear shallow water'),
  ('european-eel', 'European Eel', 'Anguilla anguilla', 'freshwater-fish', 'A critically endangered, snake-like fish that migrates across the Atlantic to breed.', 'Rivers, canals, lakes and estuaries', 'Summer evenings and warm, wet nights'),
  ('three-spined-stickleback', 'Three-spined Stickleback', 'Gasterosteus aculeatus', 'freshwater-fish', 'A tiny fish with three dorsal spines; breeding males have a red throat.', 'Ponds, streams, ditches and estuaries', 'April to July'),
  ('arctic-charr', 'Arctic Charr', 'Salvelinus alpinus', 'freshwater-fish', 'A rare relict fish of cold, deep upland lakes, left over from the last ice age.', 'A handful of deep, cold upland lakes', 'Only in a few lakes; seek local guidance'),
  ('grayling', 'Grayling', 'Thymallus thymallus', 'freshwater-fish', 'A silver-grey river fish with a tall, sail-like dorsal fin.', 'Clean, fast-flowing rivers with gravel beds', 'Late summer and autumn, in clear water'),
  ('basking-shark', 'Basking Shark', 'Cetorhinus maximus', 'marine-fish', 'The second-largest fish in the world, a harmless filter feeder that cruises with its dorsal fin above the surface.', 'Coastal surface waters, especially around western Britain', 'May to August, on calm bright days'),
  ('ocean-sunfish', 'Ocean Sunfish', 'Mola mola', 'marine-fish', 'A giant, flat-bodied fish often seen basking at the surface on its side.', 'Open coastal and offshore waters', 'Midsummer to autumn, on calm days'),
  ('atlantic-mackerel', 'Atlantic Mackerel', 'Scomber scombrus', 'marine-fish', 'A streamlined, striped fish that forms dense summer shoals around the coast.', 'Coastal waters and open sea', 'Summer, from piers and boat trips'),
  ('perch', 'Perch', 'Perca fluviatilis', 'freshwater-fish', 'A green-gold fish with dark vertical bars, a spiny dorsal fin and red-orange fins; it hunts in small shoals.', 'Lakes, ponds, canals and slow rivers', 'Spring to autumn, around reeds, pontoons and submerged cover'),
  ('roach', 'Roach', 'Rutilus rutilus', 'freshwater-fish', 'A silvery shoaling fish with red-orange eyes and fins, one of the most widespread coarse fish in slow rivers and lakes.', 'Slow rivers, canals, lakes and ponds', 'Year-round, in shoals near weed and overhanging cover'),
  ('rudd', 'Rudd', 'Scardinius erythrophthalmus', 'freshwater-fish', 'A deep-bodied golden fish with bright red fins and an upturned mouth, often feeding near the surface among weed.', 'Weedy lakes, ponds and slow rivers', 'Late spring to early autumn, on warm calm days'),
  ('chub', 'Chub', 'Squalius cephalus', 'freshwater-fish', 'A chunky, blunt-headed river fish with large dark-edged scales; shy and quick to spook, it lurks under overhanging trees.', 'Medium to large rivers, in pools under overhanging cover', 'Summer and autumn, in clear water'),
  ('dace', 'Dace', 'Leuciscus leuciscus', 'freshwater-fish', 'A slim, silvery river fish with a pale yellowish eye, found in lively shoals in clear, flowing water.', 'Clean, fast-flowing rivers and streams', 'Summer to autumn, in streamy runs and below weirs'),
  ('gudgeon', 'Gudgeon', 'Gobio gobio', 'freshwater-fish', 'A small, bottom-feeding fish with a barbel at each corner of its mouth and a spotted back, living on gravel and sand.', 'Gravelly rivers, canals and some lakes', 'Year-round, over clean gravel and sand'),
  ('minnow', 'Minnow', 'Phoxinus phoxinus', 'freshwater-fish', 'A tiny shoaling fish, olive above with a dark stripe; breeding males flush with red and black.', 'Clear streams, rivers and lake margins', 'Spring to summer, in shallow, clear water'),
  ('bullhead', 'Bullhead', 'Cottus gobio', 'freshwater-fish', 'A small, mottled fish with a broad flat head and a huge mouth, hiding under stones on the bed of clear streams.', 'Clean, stony streams and rivers', 'Year-round; look under stones in shallow, flowing water'),
  ('stone-loach', 'Stone Loach', 'Barbatula barbatula', 'freshwater-fish', 'A slim, mottled fish with six barbels that hides under stones and weed by day and feeds on the stream bed at night.', 'Clear, stony streams and rivers', 'Year-round; most active at dusk and after dark'),
  ('tench', 'Tench', 'Tinca tinca', 'freshwater-fish', 'A thick-set, olive-bronze fish with tiny scales, small red eyes and rounded fins, found in still, weedy water.', 'Weedy ponds, lakes and slow rivers', 'Late spring to early autumn, at dawn among lily pads and weed'),
  ('common-bream', 'Common Bream', 'Abramis brama', 'freshwater-fish', 'A tall, flat-sided, bronze-silver fish with a long anal fin that grazes the bottom in big shoals.', 'Slow rivers, canals and large lakes', 'Summer to autumn; shoals feed over the bed in calm water'),
  ('barbel', 'Barbel', 'Barbus barbus', 'freshwater-fish', 'A powerful, torpedo-shaped river fish with four barbels around its mouth, fond of fast gravelly runs and weir pools.', 'Clean, fast-flowing lowland rivers with gravel', 'Summer and autumn, in streamy runs and weir pools'),
  ('nine-spined-stickleback', 'Nine-spined Stickleback', 'Pungitius pungitius', 'freshwater-fish', 'A tiny, spiny fish with nine short dorsal spines; breeding males turn black.', 'Weedy ponds, ditches, drains and slow streams', 'April to July, in weedy shallows'),
  ('bleak', 'Bleak', 'Alburnus alburnus', 'freshwater-fish', 'A slender, silver fish that gathers in large, flickering shoals just below the surface of slow rivers.', 'Slow, lowland rivers and canals', 'Summer, in shoals near the surface'),
  ('ruffe', 'Ruffe', 'Gymnocephalus cernua', 'freshwater-fish', 'A small, spiny, olive-brown relative of the perch with a single spotted dorsal fin, living near the bed of slow water.', 'Slow rivers, canals and a few large lakes', 'Year-round, near the bottom in slow, deep water'),
  ('brook-lamprey', 'Brook Lamprey', 'Lampetra planeri', 'freshwater-fish', 'A small, eel-like, jawless fish; adults gather to spawn in gravel nests in small streams after years as buried larvae.', 'Small, clean streams with gravel and silt', 'Spring spawning, in shallow gravel runs'),
  ('river-lamprey', 'River Lamprey', 'Lampetra fluviatilis', 'freshwater-fish', 'A jawless, eel-like fish that migrates from estuaries up rivers to spawn on gravel; adults have a round sucker mouth.', 'Estuaries and the lower reaches of clean rivers', 'Spring spawning, on shallow gravel'),
  ('sea-lamprey', 'Sea Lamprey', 'Petromyzon marinus', 'freshwater-fish', 'The largest UK lamprey: a mottled, jawless, eel-like fish that runs up rivers to spawn in large gravel nests.', 'Estuaries and clean rivers with gravel beds', 'Late spring to early summer, on spawning gravel'),
  ('spined-loach', 'Spined Loach', 'Cobitis taenia', 'freshwater-fish', 'A slim, spotted, eel-like fish with a tiny spine beneath each eye, found in a few slow lowland rivers and drains.', 'Slow, sandy lowland rivers and drains in eastern England', 'Summer, on sandy beds in slow water'),
  ('smelt', 'Smelt', 'Osmerus eperlanus', 'freshwater-fish', 'A slender, silvery fish that smells of cucumber, living in estuaries and running up tidal rivers to spawn.', 'Estuaries and the tidal reaches of a few rivers', 'Late winter to spring, during spawning runs'),
  ('twaite-shad', 'Twaite Shad', 'Alosa fallax', 'freshwater-fish', 'A silvery, herring-like fish with a dark spot behind the gill cover that runs up a few rivers from the sea to spawn.', 'Estuaries and a few large rivers', 'Late April to June, on spawning runs; seek local guidance'),
  ('crucian-carp', 'Crucian Carp', 'Carassius carassius', 'freshwater-fish', 'A deep-bodied, golden-bronze carp with a rounded tail and no barbels, living in small weedy ponds.', 'Small, weedy ponds, mainly in south-east England', 'Summer, in warm, weedy shallows'),
  ('powan', 'Powan', 'Coregonus lavaretus', 'freshwater-fish', 'A silvery whitefish found in only a few cold, deep lakes, where it is also known as the schelly and the gwyniad.', 'A handful of cold, deep lakes', 'Only in a few lakes; seek local guidance'),
  ('vendace', 'Vendace', 'Coregonus albula', 'freshwater-fish', 'A rare, silvery whitefish and one of Britain''s rarest freshwater fish, found in very few cold, deep lakes.', 'A very few cold, deep lakes in northern England', 'Only in a few lakes; seek local guidance'),
  ('pollan', 'Pollan', 'Coregonus pollan', 'freshwater-fish', 'A rare, silvery whitefish of cold, deep Irish loughs, a close relative of the powan and vendace.', 'Lough Neagh and a few other deep loughs', 'Only in a few loughs; seek local guidance'),
  ('common-carp', 'Common Carp', 'Cyprinus carpio', 'freshwater-fish', 'A big, deep-bodied fish with a long dorsal fin and two pairs of barbels, introduced centuries ago and now widespread.', 'Lakes, ponds, canals and slow rivers', 'Late spring to early autumn, in warm, calm water'),
  ('rainbow-trout', 'Rainbow Trout', 'Oncorhynchus mykiss', 'freshwater-fish', 'A speckled trout with a pink-red lateral band, introduced from North America and widely stocked in lakes and rivers.', 'Stocked lakes, reservoirs and some rivers', 'Spring to autumn, in cool, well-oxygenated water'),
  ('goldfish', 'Goldfish', 'Carassius auratus', 'freshwater-fish', 'An orange-gold carp relative from the ornamental pond trade, found in park ponds, canals and lakes after being released.', 'Park ponds, canals and small lakes', 'Summer, in warm, sunny shallows'),
  ('zander', 'Zander', 'Sander lucioperca', 'freshwater-fish', 'A long, perch-like predator with glassy eyes and fang-like teeth, introduced from Europe and found in murky, slow water.', 'Slow, turbid rivers, canals and some lakes', 'Autumn to spring, in low light and cloudy water'),
  ('silver-bream', 'Silver Bream', 'Blicca bjoerkna', 'freshwater-fish', 'A flat-sided, silvery bream with large red-tinged eyes and pinkish fins, smaller than the common bream and often shoaling with it.', 'Slow rivers, canals and lakes in eastern England', 'Summer to autumn, in shoals over the bed of slow water'),
  ('wels-catfish', 'Wels Catfish', 'Silurus glanis', 'freshwater-fish', 'Europe''s largest freshwater fish: a huge, scaleless, flat-headed catfish with long whiskers, introduced to a few lakes and rivers.', 'A small number of lakes and rivers in England', 'Summer, at dusk and after dark in warm water'),
  ('pumpkinseed', 'Pumpkinseed', 'Lepomis gibbosus', 'freshwater-fish', 'A small, brilliantly coloured North American sunfish with an orange belly and a red-tipped gill flap.', 'A few warm, weedy ponds and lakes', 'Summer, around weed beds and cover'),
  ('topmouth-gudgeon', 'Topmouth Gudgeon', 'Pseudorasbora parva', 'freshwater-fish', 'A tiny, invasive fish from Asia with an upturned mouth that spreads through ponds and ditches and harms native species.', 'Small ponds, ditches and lake margins', 'Summer, in warm, still shallows'),
  ('grass-carp', 'Grass Carp', 'Ctenopharyngodon idella', 'freshwater-fish', 'A long, torpedo-shaped, olive-grey carp from Asia, stocked in some lakes to eat weed and rarely breeding here.', 'Stocked lakes, ponds and weedy waters', 'Summer, in warm, weedy shallows')
) as v(slug, common_name, scientific_name, group_slug, summary, habitat, best_time)
join public.groups g on g.slug = v.group_slug
on conflict (slug) do update set
  common_name = excluded.common_name, scientific_name = excluded.scientific_name, group_id = excluded.group_id,
  summary = excluded.summary, habitat = excluded.habitat, best_time = excluded.best_time;

